window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-40c9680208741bb4"]={"versions": [{"id": "FIG-40c9680208741bb4", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Architektur- und Komponentendiagramm (Beispielübersicht). Das Diagramm veranschaulicht die Einbettung des Update and Configuration Management Masters (UCM Master) in die Gesamtfahrzeugarchitektur (Vehicle) der AUTOSAR Adaptive Platform und zeigt die Interaktion mit externen Instanzen (Backend, Garage tester), internen Funktionsgruppen (Vehicle State Manager, Driver Interaction, Diagnostic Management) sowie heterogenen Steuergeräten (Classic AUTOSAR, Non-AUTOSAR).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das System gliedert sich in externe Entitäten, Übertragungsmedien und fahrzeuginterne Steuergeräteblöcke:</p>\n<ul class=\"fig-list\">\n<li><strong>Externe Entitäten</strong>: <code>Backend</code> und <code>Garage tester</code>, angebunden über ein <code>Communication medium</code> und einen fahrzeuginternen Kanal (<code>Communication channel Ethernet or CAN/DoCAN Bus</code>).</li>\n<li><strong>Adaptive AUTOSAR Machine (primär)</strong>:</li>\n<li>Applikationsebene (oberhalb der gestrichelten Plattformgrenze): <code>OTA client</code>, <code>Driver Interaction</code>, <code>Vehicle State Manager</code>, <code>Diagnostic application</code>.</li>\n<li>Plattformebene: <code>UCM Master</code> mit unterlagertem <code>UCM</code> (lokaler UCM), <code>Device driver (DPDU API ISO22900-2)</code>.</li>\n<li><strong>Adaptive AUTOSAR Machine (sekundär / Backup)</strong>:</li>\n<li>Applikationsebene: <code>Diagnostic application</code>.</li>\n<li>Plattformebene: Schraffierter <code>UCM Master</code> (mit Annotation <code>Optional backup master: If one UCM Master is failing, another could take over Master role</code>), lokaler <code>UCM</code>, <code>Diagnostic Manager</code>.</li>\n<li><strong>Schnittstellen & Busse</strong>:</li>\n<li><code>DoIP</code> kapselt die Kommunikation über die Adaptive Machines und bindet den <code>Diagnostic Manager</code> an den Diagnosekanal an.</li>\n<li>Der <code>OTA client</code> empfängt externe Aktualisierungsdaten über den Kommunikationskanal.</li>\n<li>Der primäre <code>UCM Master</code> steuert über Punkt-zu-Punkt-Beziehungen <code>Driver Interaction</code>, <code>Vehicle State Manager</code>, <code>Diagnostic application</code> sowie den lokalen <code>UCM</code> und den <code>Device driver (DPDU API ISO22900-2)</code>.</li>\n<li>Über den <code>Device driver</code> besteht eine <code>UDS</code>-Verbindung zu einer <code>Classic AUTOSAR ECU</code>.</li>\n<li>Der primäre <code>UCM Master</code> ist mit der sekundären Machine (lokaler <code>UCM</code> und schraffierter Backup <code>UCM Master</code>) über Steuerleitungen verknüpft.</li>\n<li><strong>Weitere Steuergeräteverbünde</strong>:</li>\n<li><code>Physical box #1</code>: Enthält Mischkonfigurationen (<code>AUTOSAR</code>, unbeschrifteter Block, <code>Ad AUTOSAR</code>), verbunden mit <code>Non AUTOSAR ECU</code> und <code>Classic AUTOSAR ECU</code>.</li>\n<li><code>Physical box #2 (HW Element ECU)</code>: Enthält <code>Classic AUTOSAR (ECU instance)</code> und <code>Non AUTOSAR</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li>Ein Update-Paket gelangt vom <code>Backend</code> oder <code>Garage tester</code> über das Kommunikationsmedium und den Fahrzeugkanal an den <code>OTA client</code>.</li>\n<li>Der <code>OTA client</code> übergibt die Daten an den primären <code>UCM Master</code>.</li>\n<li>Der <code>UCM Master</code> koordiniert den Fahrzeugzustand mit dem <code>Vehicle State Manager</code>, holt Nutzerzustimmungen über <code>Driver Interaction</code> ein und steuert Diagnoseaktivitäten über die <code>Diagnostic application</code>.</li>\n<li>Für die Aktualisierung unterlagerter Steuergeräte adressiert der <code>UCM Master</code> den lokalen <code>UCM</code> der eigenen Maschine, den <code>Device driver (DPDU API ISO22900-2)</code> zur UDS-Flashexekution auf Classic-ECUs sowie über Remote-Kommunikation den lokalen <code>UCM</code> der zweiten Adaptive Machine.</li>\n<li>Fällt der primäre <code>UCM Master</code> aus, übernimmt der <code>Optional backup master</code> auf der zweiten Adaptive Machine dessen Rolle.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Das Diagramm dient als exemplarisches Architekturüberblicksbild (non-normativ / informativ gekennzeichnet durch den Titel „Example of UCM Master architecture overview within a vehicle“).</li>\n<li>Es skizziert das Redundanzkonzept für Hochverfügbarkeit (Backup UCM Master) und die Dualität zwischen fahrzeugweitem Update-Master (UCM Master) und maschinenlokalem Ausführungs-Agenten (UCM).</li>\n<li>Die Anbindung klassischer ECUs über die ISO 22900-2 (D-PDU API) spezifiziert den Übergang von serviceorientierter Adaptive-Kommunikation auf standardisierte UDS-Diagnoseprotokolle.</li>\n</ul>"}, {"id": "FIG-751483a62a4b7fe2", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Architektur- und Komponentendiagramm (Beispielübersicht). Das Diagramm veranschaulicht die Einbettung des Update and Configuration Management Masters (UCM Master) in die Gesamtfahrzeugarchitektur (Vehicle) der AUTOSAR Adaptive Platform und zeigt die Interaktion mit externen Instanzen (Backend, Garage tester), internen Funktionsgruppen (Vehicle State Manager, Driver Interaction, Diagnostic Management) sowie heterogenen Steuergeräten (Classic AUTOSAR, Non-AUTOSAR).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das System gliedert sich in externe Entitäten, Übertragungsmedien und fahrzeuginterne Steuergeräteblöcke:</p>\n<ul class=\"fig-list\">\n<li><strong>Externe Entitäten</strong>: <code>Backend</code> und <code>Garage tester</code>, angebunden über ein <code>Communication medium</code> und einen fahrzeuginternen Kanal (<code>Communication channel Ethernet or CAN/DoCAN Bus</code>).</li>\n<li><strong>Adaptive AUTOSAR Machine (primär)</strong>:</li>\n<li>Applikationsebene (oberhalb der gestrichelten Plattformgrenze): <code>OTA client</code>, <code>Driver Interface</code>, <code>Vehicle State Manager</code>, <code>Flashing Adapter</code>.</li>\n<li>Plattformebene: <code>UCM Master</code> mit unterlagertem <code>UCM</code> (lokaler UCM), Diagnosetreibereinheit bestehend aus <code>ISO 22900-2 (D-PDU API)</code> sowie zwei Kommunikationsmodulen: <code>VCI Module 1 CAN</code> und <code>VCI Module 2 Ethernet</code>.</li>\n<li><strong>Adaptive AUTOSAR Machine (sekundär / Backup)</strong>:</li>\n<li>Applikationsebene: <code>Diagnostic application</code>.</li>\n<li>Plattformebene: <code>UCM Master</code> (als <code>Optional backup master</code> annotiert: „If one UCM Master is failing, another could take over Master role“), lokaler <code>UCM</code>, <code>Diagnostic Manager</code>.</li>\n<li><strong>Schnittstellen & Busse</strong>:</li>\n<li><code>DoIP</code> umfasst die Kommunikation zwischen den Adaptive Machines und bindet den <code>Diagnostic Manager</code> an den Diagnosekanal an.</li>\n<li>Der <code>OTA client</code> empfängt externe Daten über den Kommunikationskanal und ist mit dem <code>Flashing Adapter</code> verbunden.</li>\n<li>Der <code>UCM Master</code> ist mit dem <code>Flashing Adapter</code>, <code>Driver Interface</code>, <code>Vehicle State Manager</code>, dem maschinenlokalen <code>UCM</code>, der <code>Diagnostic application</code> der zweiten Machine sowie dem entfernten lokalen <code>UCM</code> und dem Backup <code>UCM Master</code> verbunden.</li>\n<li>Der <code>Flashing Adapter</code> agiert als Schnittstelle zur <code>ISO 22900-2 (D-PDU API)</code>.</li>\n<li>Über <code>VCI Module 1 CAN</code> führt eine Schnittstelle <code>UDS on CAN</code> zu einer <code>Classic AUTOSAR ECU</code>.</li>\n<li>Über <code>VCI Module 2 Ethernet</code> führt eine Schnittstelle <code>UDS on DoIP</code> zu einer weiteren <code>Classic AUTOSAR ECU</code>.</li>\n<li><strong>Weitere Steuergeräteverbünde</strong>:</li>\n<li><code>Physical box #1</code>: Enthält <code>AUTOSAR</code>, <code>Non AUTOSAR</code> und zweifach <code>Ad AUTOSAR</code>, angebunden an <code>Non AUTOSAR ECU</code> und <code>Classic AUTOSAR ECU</code>.</li>\n<li><code>Physical box #2 (HW Element ECU)</code>: Enthält <code>Classic AUTOSAR (ECU instance)</code> und <code>Non AUTOSAR</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li>Ein Update-Paket gelangt vom <code>Backend</code> oder <code>Garage tester</code> über das Kommunikationsmedium und den fahrzeuginternen Kommunikationskanal an den <code>OTA client</code>.</li>\n<li>Der <code>OTA client</code> leitet die Update-Informationen an den <code>Flashing Adapter</code> weiter, welcher mit dem <code>UCM Master</code> interagiert.</li>\n<li>Der <code>UCM Master</code> synchronisiert Randbedingungen mit dem <code>Vehicle State Manager</code>, interagiert über das <code>Driver Interface</code> und koordiniert Diagnosezustände über die <code>Diagnostic application</code>.</li>\n<li>Die eigentliche Flashexekution für Classic-Steuergeräte wird über den <code>Flashing Adapter</code> an die <code>ISO 22900-2 (D-PDU API)</code> delegiert, die über <code>VCI Module 1 CAN</code> (<code>UDS on CAN</code>) bzw. <code>VCI Module 2 Ethernet</code> (<code>UDS on DoIP</code>) die jeweiligen Ziel-ECUs bedient.</li>\n<li>Die Maschinenaktualisierung erfolgt lokal über den jeweiligen <code>UCM</code>.</li>\n<li>Fällt der primäre <code>UCM Master</code> aus, übernimmt der <code>Optional backup master</code> auf der sekundären Adaptive Machine dessen Rolle.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Das Diagramm dient als exemplarisches Architekturüberblicksbild (non-normativ / informativ gemäß Titel „Example of UCM Master architecture overview within a vehicle“).</li>\n<li>Es konkretisiert die Diagnose- und Flash-Infrastruktur für Classic AUTOSAR ECUs durch die funktionale Trennung in <code>Flashing Adapter</code>, D-PDU-API-Schicht (<code>ISO 22900-2</code>) und protokollspezifische VCI-Module (<code>UDS on CAN</code>, <code>UDS on DoIP</code>).</li>\n<li>Die Entkopplung des UCM Masters über den Flashing Adapter verdeutlicht die modulare Kapselung fahrzeugspezifischer Flash-Abläufe gegenüber der standardisierten UCM-Master-Zustandsverwaltung.</li>\n</ul>"}], "trans": [{"from": "FIG-40c9680208741bb4", "to": "FIG-751483a62a4b7fe2", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong>Flashing Adapter</strong>: Neu eingefügt als Applikationsebene-Komponente auf der primären Adaptive AUTOSAR Machine, geschaltet zwischen UCM Master, OTA client und Fahrzeugzustands-/Fahrer-Schnittstelle.</li>\n<li><strong>Device driver / D-PDU API</strong>: Die bisherige generische Box <code>Device driver (DPDU API ISO22900-2)</code> wurde ersetzt durch eine strukturierte Einheit aus <code>ISO 22900-2 (D-PDU API)</code> und darunterliegenden Modulen <code>VCI Module 1 CAN</code> sowie <code>VCI Module 2 Ethernet</code>.</li>\n<li><strong>Anbindung UDS / Classic AUTOSAR</strong>: Statt einer einzelnen generischen UDS-Verbindung zu einer Classic AUTOSAR ECU existieren nun zwei differenzierte Pfade: <code>UDS on CAN</code> über <code>VCI Module 1 CAN</code> und <code>UDS on DoIP</code> über <code>VCI Module 2 Ethernet</code> zu jeweils einer Classic AUTOSAR ECU.</li>\n<li><strong>Schnittstellen & Interaktion</strong>: Der UCM Master kommuniziert mit dem Flashing Adapter; dieser bindet direkt an <code>ISO 22900-2 (D-PDU API)</code> an (statt direkter Anbindung von UCM Master an den Device driver).</li>\n<li><strong>Driver Interaction</strong>: Umbenannt in <code>Driver Interface</code>.</li>\n<li><strong>Physical box #1</strong>: Die mittlere graue Säule ist nun explizit mit <code>Non AUTOSAR</code> beschriftet.</li>\n<li><strong>Backup UCM Master</strong>: Schraffierte Darstellung durch einheitliche Fläche ersetzt.</li>\n</ul>"}]};
